<?php declare(strict_types=1); $isHttps = isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off'; session_set_cookie_params([ 'lifetime' => 0, 'path' => '/', 'secure' => $isHttps, 'httponly' => true, 'samesite' => 'Lax', ]); session_start(); if ($_SERVER['REQUEST_METHOD'] !== 'POST') { header('Allow: POST'); http_response_code(405); exit('Méthode non autorisée.'); } // Vérification CSRF $csrfToken = (string) ($_POST['csrf_token'] ?? ''); $sessionToken = $_SESSION['csrf_token'] ?? null; if ( !is_string($sessionToken) || $sessionToken === '' || !hash_equals($sessionToken, $csrfToken) ) { http_response_code(403); exit('Requête invalide. Veuillez actualiser la page.'); } // Récupération des paramètres du cookie $params = session_get_cookie_params(); $sessionName = session_name(); // Suppression des données de session $_SESSION = []; // Suppression du cookie if (ini_get('session.use_cookies')) { setcookie( $sessionName, '', [ 'expires' => time() - 3600, 'path' => $params['path'], 'domain' => $params['domain'], 'secure' => $params['secure'], 'httponly' => $params['httponly'], 'samesite' => $params['samesite'] ?? 'Lax', ] ); } // Destruction de la session serveur session_destroy(); // Empêcher la mise en cache de la page header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0'); header('Pragma: no-cache'); // Redirection header('Location: connexion.php', true, 303); exit;
